CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE workflows (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, description text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, definition jsonb NOT NULL, webhook_token text NOT NULL UNIQUE, next_run_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workflow_versions (workflow_id uuid NOT NULL REFERENCES workflows(id), version integer NOT NULL, definition jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workflow_id,version));
CREATE TABLE credentials (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, encrypted_value text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE executions (id uuid PRIMARY KEY, workflow_id uuid NOT NULL REFERENCES workflows(id), owner_id uuid NOT NULL REFERENCES users(id), workflow_name text NOT NULL, version integer NOT NULL, definition jsonb NOT NULL, input jsonb NOT NULL, status text NOT NULL DEFAULT 'QUEUED', trigger_type text NOT NULL, dedupe_key text, created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, finished_at timestamptz, next_attempt_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, cancel_requested boolean NOT NULL DEFAULT false, error text, UNIQUE(workflow_id,dedupe_key));
CREATE TABLE steps (execution_id uuid NOT NULL REFERENCES executions(id) ON DELETE CASCADE, node_id text NOT NULL, label text NOT NULL, type text NOT NULL, status text NOT NULL DEFAULT 'PENDING', attempts integer NOT NULL DEFAULT 0, output jsonb, error text, started_at timestamptz, finished_at timestamptz, PRIMARY KEY(execution_id,node_id));
CREATE TABLE outbox (id bigserial PRIMARY KEY, execution_id uuid NOT NULL REFERENCES executions(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX executions_ready ON executions(next_attempt_at) WHERE status IN ('QUEUED','RUNNING','RETRYING');
CREATE INDEX executions_owner ON executions(owner_id,created_at DESC);
CREATE INDEX workflows_owner ON workflows(owner_id);
